import { promises as fs } from 'fs';
import path from 'path';
import { randomUUID } from 'crypto';

export type BookStatus = 'reading' | 'finished';

export interface Book {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  addedAt: string;
  finishedAt: string | null;
}

export interface NewBookInput {
  title: string;
  author: string;
  notes?: string;
}

// The JSON file lives at <cwd>/data/books.json by default. Override the path
// with the BOOKS_FILE env var (handy for tests or alternate deployments).
function dataFile(): string {
  return process.env.BOOKS_FILE || path.join(process.cwd(), 'data', 'books.json');
}

async function ensureFile(): Promise<void> {
  const file = dataFile();
  await fs.mkdir(path.dirname(file), { recursive: true });
  try {
    await fs.access(file);
  } catch {
    await fs.writeFile(file, '[]', 'utf8');
  }
}

export async function getAllBooks(): Promise<Book[]> {
  await ensureFile();
  const raw = await fs.readFile(dataFile(), 'utf8');
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as Book[]) : [];
  } catch {
    return [];
  }
}

async function writeBooks(books: Book[]): Promise<void> {
  await ensureFile();
  await fs.writeFile(dataFile(), JSON.stringify(books, null, 2), 'utf8');
}

export async function getBookById(id: string): Promise<Book | undefined> {
  const books = await getAllBooks();
  return books.find((b) => b.id === id);
}

export async function createBook(input: NewBookInput): Promise<Book> {
  const books = await getAllBooks();
  const book: Book = {
    id: randomUUID(),
    title: input.title.trim(),
    author: input.author.trim(),
    notes: (input.notes ?? '').trim(),
    status: 'reading',
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.unshift(book);
  await writeBooks(books);
  return book;
}

export async function setBookStatus(id: string, status: BookStatus): Promise<Book | undefined> {
  const books = await getAllBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return undefined;
  book.status = status;
  book.finishedAt = status === 'finished' ? new Date().toISOString() : null;
  await writeBooks(books);
  return book;
}

export async function updateBookNotes(id: string, notes: string): Promise<Book | undefined> {
  const books = await getAllBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return undefined;
  book.notes = notes;
  await writeBooks(books);
  return book;
}

export async function deleteBook(id: string): Promise<boolean> {
  const books = await getAllBooks();
  const next = books.filter((b) => b.id !== id);
  if (next.length === books.length) return false;
  await writeBooks(next);
  return true;
}

