'use server';

import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import {
  createBook,
  deleteBook,
  setBookStatus,
  updateBookNotes,
} from '@/lib/books';

export type AddBookResult =
  | { ok: true; id: string }
  | { ok: false; error: string };

export async function addBookAction(formData: FormData): Promise<AddBookResult> {
  const title = String(formData.get('title') ?? '').trim();
  const author = String(formData.get('author') ?? '').trim();
  const notes = String(formData.get('notes') ?? '').trim();

  if (!title || !author) {
    return { ok: false, error: 'Title and author are required.' };
  }

  const book = await createBook({ title, author, notes });
  revalidatePath('/');
  return { ok: true, id: book.id };
}

export async function markFinishedAction(id: string): Promise<void> {
  await setBookStatus(id, 'finished');
  revalidatePath('/');
  revalidatePath(`/books/${id}`);
}

export async function markReadingAction(id: string): Promise<void> {
  await setBookStatus(id, 'reading');
  revalidatePath('/');
  revalidatePath(`/books/${id}`);
}

export async function saveNotesAction(id: string, notes: string): Promise<{ ok: boolean }> {
  const book = await updateBookNotes(id, notes);
  revalidatePath(`/books/${id}`);
  revalidatePath('/');
  return { ok: Boolean(book) };
}

export async function deleteBookAction(id: string): Promise<void> {
  await deleteBook(id);
  revalidatePath('/');
  redirect('/');
}

