'use client';

import { useState, useTransition } from 'react';
import Link from 'next/link';
import { addBookAction, type AddBookResult } from '@/app/actions';

export function AddBookForm() {
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<AddBookResult | null>(null);

  function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const formData = new FormData(form);
    setError(null);
    setResult(null);
    startTransition(async () => {
      const res = await addBookAction(formData);
      setResult(res);
      if (res.ok) form.reset();
      else setError(res.error);
    });
  }

  return (
    <form onSubmit={onSubmit} className="add-form card">
      <h2>Add a book</h2>
      <div className="field">
        <label htmlFor="title">Title</label>
        <input id="title" name="title" type="text" required placeholder="The Great Gatsby" />
      </div>
      <div className="field">
        <label htmlFor="author">Author</label>
        <input id="author" name="author" type="text" required placeholder="F. Scott Fitzgerald" />
      </div>
      <div className="field">
        <label htmlFor="notes">Notes (optional)</label>
        <textarea id="notes" name="notes" rows={3} placeholder="Why am I reading this?" />
      </div>
      <div className="form-actions">
        <button type="submit" className="btn primary" disabled={pending}>
          {pending ? 'Adding…' : 'Add to reading'}
        </button>
        {error && <span className="error">{error}</span>}
        {result?.ok && (
          <span className="success">
            Added! <Link href={`/books/${result.id}`}>View book →</Link>
          </span>
        )}
      </div>
    </form>
  );
}

