'use client';

import { useState, useTransition } from 'react';
import {
  deleteBookAction,
  markFinishedAction,
  markReadingAction,
} from '@/app/actions';

export function MarkFinishedButton({ id }: { id: string }) {
  const [pending, startTransition] = useTransition();
  return (
    <button
      className="btn primary sm"
      disabled={pending}
      onClick={() => startTransition(() => markFinishedAction(id))}
    >
      {pending ? 'Marking…' : 'Mark as finished'}
    </button>
  );
}

export function MarkReadingButton({ id }: { id: string }) {
  const [pending, startTransition] = useTransition();
  return (
    <button
      className="btn sm"
      disabled={pending}
      onClick={() => startTransition(() => markReadingAction(id))}
    >
      {pending ? 'Moving…' : 'Reading again'}
    </button>
  );
}

export function DeleteBookButton({ id }: { id: string }) {
  const [pending, startTransition] = useTransition();
  return (
    <button
      className="btn danger sm"
      disabled={pending}
      onClick={() => {
        if (window.confirm('Delete this book and its notes?')) {
          startTransition(() => deleteBookAction(id));
        }
      }}
    >
      {pending ? 'Deleting…' : 'Delete'}
    </button>
  );
}

export function CopyLinkButton() {
  const [copied, setCopied] = useState(false);
  async function copy() {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      setCopied(false);
    }
  }
  return (
    <button className="btn sm" onClick={copy}>
      {copied ? 'Link copied!' : 'Copy link'}
    </button>
  );
}

