'use client';

import { useState, useTransition } from 'react';
import { saveNotesAction } from '@/app/actions';

export function NotesEditor({ id, initialNotes }: { id: string; initialNotes: string }) {
  const [notes, setNotes] = useState(initialNotes);
  const [pending, startTransition] = useTransition();
  const [saved, setSaved] = useState(false);
  const dirty = notes !== initialNotes;

  function save() {
    startTransition(async () => {
      await saveNotesAction(id, notes);
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    });
  }

  return (
    <div className="notes">
      <label htmlFor="notes">My notes</label>
      <textarea
        id="notes"
        rows={12}
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
        placeholder="Thoughts, quotes, takeaways…"
      />
      <div className="notes-actions">
        <button className="btn primary" onClick={save} disabled={pending || !dirty}>
          {pending ? 'Saving…' : 'Save notes'}
        </button>
        {saved && <span className="success">Saved!</span>}
        {dirty && !saved && <span className="hint">Unsaved changes</span>}
      </div>
    </div>
  );
}

