args.content:
:root {
  --bg: #f6f5f1;
  --card: #ffffff;
  --ink: #1f2430;
  --muted: #6b7280;
  --line: #e6e3dc;
  --accent: #4f46e5;
  --accent-ink: #ffffff;
  --danger: #b91c1c;
  --finished: #eef2ff;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

main {
  max-width: 760px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

h1 { font-size: 2rem; margin: 0 0 0.25rem; }
h2 { font-size: 1.15rem; margin: 0 0 1rem; }
h3 { font-size: 1.05rem; margin: 0 0 0.15rem; }

p { margin: 0; }

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

.muted { color: var(--muted); font-size: 0.9rem; }

/* Cards */
.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1.25rem;
}

.add-form { margin: 1.5rem 0 2.25rem; }

.field { margin-bottom: 0.9rem; }
.field label,
.notes label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.3rem;
}

input, textarea {
  width: 100%;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  font: inherit;
  color: var(--ink);
  background: #fff;
}
input:focus, textarea:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  border-color: var(--accent);
}
textarea { resize: vertical; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  padding: 0.5rem 0.9rem;
  border-radius: 8px;
  font: inherit;
  cursor: pointer;
}
.btn:hover:not(:disabled) { border-color: #cfc9bd; }
.btn:disabled { opacity: 0.55; cursor: default; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn.danger { color: var(--danger); border-color: #f3c9c9; }
.btn.danger:hover:not(:disabled) { background: #fdf2f2; }
.btn.sm { padding: 0.35rem 0.7rem; font-size: 0.85rem; }

.form-actions, .notes-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}
.error { color: var(--danger); font-size: 0.9rem; }
.success { color: #15803d; font-size: 0.9rem; }
.hint { color: var(--muted); font-size: 0.85rem; }

/* Lists */
section { margin-bottom: 2.25rem; }
.grid { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.75rem; }

.card.list-item { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.card.list-item .meta { min-width: 0; }
.card.list-item a { color: var(--ink); }
.card.list-item a:hover { text-decoration: none; }
.card.list-item a:hover h3 { color: var(--accent); }
.card.list-item.finished { background: var(--finished); }
.card.list-item.finished h3 { text-decoration: line-through; color: var(--muted); }
.card.list-item .author { color: var(--muted); font-size: 0.9rem; }

.empty {
  color: var(--muted);
  background: var(--card);
  border: 1px dashed var(--line);
  border-radius: 12px;
  padding: 1.25rem;
  text-align: center;
}

/* Detail page */
.back { display: inline-block; margin-bottom: 1rem; font-size: 0.9rem; }
.book-detail h1 { margin-bottom: 0.15rem; }
.book-detail .author { color: var(--muted); font-size: 1.05rem; margin-bottom: 0.4rem; }
.book-detail .status {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  background: var(--finished);
  color: var(--accent);
  margin-bottom: 1.25rem;
}
.book-detail .actions {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
  margin-bottom: 1.5rem;
}
.notes { margin-top: 0.5rem; }
.notes textarea { margin-top: 0.3rem; }

