args.content:
import { getAllBooks } from '@/lib/books';
import { AddBookForm } from '@/components/AddBookForm';
import { MarkFinishedButton, MarkReadingButton } from '@/components/BookActions';

export const dynamic = 'force-dynamic';

export default async function HomePage() {
  const books = await getAllBooks();
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  return (
    <main>
      <header>
        <h1>Reading List</h1>
        <p className="muted">What I&apos;m reading and what I&apos;ve finished.</p>
      </header>

      <AddBookForm />

      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing in progress yet — add a book above.</p>
        ) : (
          <ul className="grid">
            {reading.map((book) => (
              <li key={book.id} className="card list-item">
                <a className="meta" href={`/books/${book.id}`}>
                  <h3>{book.title}</h3>
                  <p className="author">{book.author}</p>
                </a>
                <MarkFinishedButton id={book.id} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">Nothing finished yet.</p>
        ) : (
          <ul className="grid">
            {finished.map((book) => (
              <li key={book.id} className="card list-item finished">
                <a className="meta" href={`/books/${book.id}`}>
                  <h3>{book.title}</h3>
                  <p className="author">{book.author}</p>
                </a>
                <MarkReadingButton id={book.id} />
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}

