import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  createBook,
  deleteBook,
  getAllBooks,
  getBookById,
  setBookStatus,
  updateBookNotes,
} from './books';

const tmp = mkdtempSync(join(tmpdir(), 'books-test-'));
const file = join(tmp, 'books.json');

beforeEach(() => {
  process.env.BOOKS_FILE = file;
});

afterEach(async () => {
  try {
    rmSync(tmp, { recursive: true, force: true });
  } catch {
    // ignore
  }
  mkdtempSync(join(tmpdir(), 'books-test-'));
});

describe('books storage', () => {
  it('starts empty and creates a book that is "reading"', async () => {
    expect(await getAllBooks()).toEqual([]);

    const book = await createBook({ title: '  Piranesi  ', author: 'Susanna Clarke' });
    expect(book.title).toBe('Piranesi');
    expect(book.author).toBe('Susanna Clarke');
    expect(book.status).toBe('reading');
    expect(book.finishedAt).toBeNull();
    expect(book.id).toMatch(/[0-9a-f-]{36}/i);

    const all = await getAllBooks();
    expect(all).toHaveLength(1);
    expect(all[0].id).toBe(book.id);
  });

  it('persists to the JSON file on disk', async () => {
    const book = await createBook({ title: 'T', author: 'A', notes: '  hi  ' });
    const onDisk = JSON.parse(readFileSync(file, 'utf8')) as Awaited<ReturnType<typeof getAllBooks>>;
    expect(onDisk).toHaveLength(1);
    expect(onDisk[0].id).toBe(book.id);
    expect(onDisk[0].notes).toBe('hi');
  });

  it('marks a book finished then back to reading, toggling finishedAt', async () => {
    const book = await createBook({ title: 'T', author: 'A' });

    const finished = await setBookStatus(book.id, 'finished');
    expect(finished?.status).toBe('finished');
    expect(finished?.finishedAt).not.toBeNull();

    const reading = await setBookStatus(book.id, 'reading');
    expect(reading?.status).toBe('reading');
    expect(reading?.finishedAt).toBeNull();
  });

  it('updates notes and looks a book up by id', async () => {
    const book = await createBook({ title: 'T', author: 'A' });
    await updateBookNotes(book.id, 'great so far');
    const found = await getBookById(book.id);
    expect(found?.notes).toBe('great so far');
  });

  it('deletes a book', async () => {
    const book = await createBook({ title: 'T', author: 'A' });
    expect(await deleteBook(book.id)).toBe(true);
    expect(await getBookById(book.id)).toBeUndefined();
    expect(await deleteBook(book.id)).toBe(false);
  });
});

